<script setup>
import {computed,ref} from 'vue';import {store,estado,hoy,nombreCurso,porcentaje,alertas,plazo,cargarDemo,cambiarEstado} from '../store';
const error=ref(''),cargando=ref(false);
const proximas=computed(()=>store.tareas.filter(t=>t.estado!=='Completado'&&t.fecha>=hoy()).sort((a,b)=>a.fecha.localeCompare(b.fecha)));
const avisos=computed(alertas),avance=computed(()=>porcentaje(store.tareas));
const indicadores=computed(()=>[{nombre:'Cursos activos',valor:store.cursos.length,icono:'bi-book',color:'violet'},{nombre:'Por completar',valor:store.tareas.filter(t=>t.estado!=='Completado').length,icono:'bi-list-check',color:'blue'},{nombre:'Completadas',valor:store.tareas.filter(t=>t.estado==='Completado').length,icono:'bi-check-circle',color:'green'},{nombre:'Vencidas',valor:store.tareas.filter(t=>estado(t)==='Vencida').length,icono:'bi-exclamation-circle',color:'red'}]);
async function demo(){cargando.value=true;error.value='';try{await cargarDemo()}catch(e){error.value=e.message}finally{cargando.value=false}}
async function completar(t){try{await cambiarEstado(t,'Completado')}catch(e){error.value=e.message}}
</script>
<template>
<div class="page-heading"><div><div class="eyebrow">PANEL GENERAL</div><h2>Resumen académico</h2><p>Organiza tu tiempo y mantén tus entregas bajo control.</p></div><RouterLink to="/actividades?nueva=1" class="btn btn-primary"><i class="bi bi-plus-lg"></i> Nueva actividad</RouterLink></div>
<div v-if="error" class="alert alert-danger">{{error}}</div>
<div v-if="!store.cursos.length" class="card p-4 mb-4 demo-card"><div><h5>Explora StudyPlan con datos de ejemplo</h5><p class="mb-2">Carga cuatro cursos y diez actividades con distintos estados y fechas relativas a hoy.</p></div><button class="btn btn-primary" :disabled="cargando" @click="demo">{{cargando?'Cargando…':'Cargar demostración'}}</button></div>
<div class="row g-3 mb-4"><div v-for="i in indicadores" :key="i.nombre" class="col-6 col-xl-3"><div class="card metric"><div :class="['metric-icon',i.color]"><i :class="['bi',i.icono]"></i></div><div class="metric-label">{{i.nombre}}</div><strong>{{i.valor}}</strong></div></div></div>
<div class="row g-4 mb-4"><div class="col-xl-8"><div class="card p-4 h-100"><div class="panel-heading"><div><h5>Próximas entregas</h5><p>Actividades pendientes ordenadas por fecha</p></div><RouterLink to="/actividades" class="subtle-link">Ver todas <i class="bi bi-arrow-right"></i></RouterLink></div><div v-if="!proximas.length" class="empty-state">No hay entregas próximas.</div><div v-for="t in proximas.slice(0,5)" :key="t.id" class="task-row"><div class="task-icon"><i class="bi bi-file-earmark-text"></i></div><div class="flex-grow-1"><strong>{{t.nombre}}</strong><div class="small text-secondary">{{nombreCurso(t.curso)}} · {{t.tipo}}</div></div><span :class="['priority',t.prioridad.toLowerCase()]">{{t.prioridad}}</span><div class="small text-secondary text-end">{{plazo(t)}}<br>{{t.fecha}}</div><button class="btn btn-sm btn-outline-success" title="Completar actividad" @click="completar(t)"><i class="bi bi-check2"></i></button></div></div></div>
<div class="col-xl-4"><div class="card p-4 h-100"><div class="panel-heading"><div><h5>Progreso general</h5><p>Tu avance del semestre</p></div></div><div class="ring mx-auto my-3" :style="{'--avance':avance+'%'}"><div><strong>{{avance}}%</strong><small>Completado</small></div></div><div v-for="c in store.cursos" :key="c.id" class="mb-3"><div class="d-flex justify-content-between small mb-1"><span>{{c.nombre}}</span><strong>{{porcentaje(store.tareas.filter(t=>t.curso===c.id))}}%</strong></div><div class="progress"><div class="progress-bar" :style="{width:porcentaje(store.tareas.filter(t=>t.curso===c.id))+'%'}"></div></div></div><RouterLink to="/progreso" class="subtle-link">Ver reporte de progreso</RouterLink></div></div></div>
<div class="card p-4"><div class="panel-heading"><div><h5><i class="bi bi-bell me-2"></i>Alertas académicas</h5><p>Vencidas y entregas en los próximos 3 días</p></div><RouterLink to="/alertas" class="subtle-link">Centro de alertas</RouterLink></div><div v-if="!avisos.length" class="empty-state">Estás al día. No hay alertas pendientes.</div><div v-for="t in avisos.slice(0,4)" :key="t.id" class="alert-row"><i :class="['bi',estado(t)==='Vencida'?'bi-exclamation-triangle text-danger':'bi-clock text-warning']"></i><div class="flex-grow-1"><strong>{{t.nombre}}</strong><div class="small text-secondary">{{nombreCurso(t.curso)}}</div></div><span class="small fw-semibold">{{plazo(t)}}</span></div></div>
</template>